use std::{fs,io::Write,path::PathBuf,process::{Command,Stdio}};
use serde_json::{json,Value};
fn run(mut c:Command,input:&str)->std::process::Output{c.stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());let mut p=c.spawn().unwrap();p.stdin.take().unwrap().write_all(input.as_bytes()).unwrap();p.wait_with_output().unwrap()}
#[test]fn local_codex_environment_keeps_dev_bridge_evidence_in_dev_control(){
 let fixture=std::env::temp_dir().join(format!("fdl-{}",&uuid::Uuid::new_v4().simple().to_string()[..8]));let local=fixture.join("CodexFloatboard-Dev/test/local");let home=fixture.join("codex");let data=local.join("CodexFloatboard/data");fs::create_dir_all(&home).unwrap();let source=PathBuf::from(env!("CARGO_BIN_EXE_FloatboardReporter"));
 let mut c=Command::new(&source);c.env("LOCALAPPDATA",&local).env("CODEX_HOME",&home).env("FLOATBOARD_PREFLIGHT","1").arg("--connect");let result=run(c,"");assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stdout));
 let bridge=local.join("CodexFloatboard/control/runtime/FloatboardBridge.exe");let fake_production=fixture.join("normal-local");let mut c=Command::new(&bridge);c.env("LOCALAPPDATA",&fake_production).env("CODEX_HOME",&home).env_remove("FLOATBOARD_PREFLIGHT").env_remove("FLOATBOARD_CONNECTION_GENERATION").env("FLOATBOARD_NO_WORKER","1").arg("--mcp");let result=run(c,"{\"id\":1,\"method\":\"initialize\"}\n");assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));let response:Value=serde_json::from_slice(&result.stdout).unwrap();assert_eq!(response["result"]["serverInfo"]["name"],"codex_floatboard_dev");
 let evidence:Value=serde_json::from_slice(&fs::read(data.join("connection-mcp.json")).unwrap()).unwrap();let receipt:Value=serde_json::from_slice(&fs::read(local.join("CodexFloatboard/control/integration.json")).unwrap()).unwrap();assert_eq!(evidence["generation"],receipt["generation"]);assert!(!fake_production.exists());
 let mut c=Command::new(&bridge);c.env("LOCALAPPDATA",&fake_production).env("CODEX_HOME",&home).env("FLOATBOARD_NO_WORKER","1").arg("--mcp");let request=json!({"id":2,"method":"tools/call","params":{"name":"hook_context","arguments":{"hook_event_name":"SessionStart","session_id":"dev-test","cwd":"C:/fixture"}}}).to_string()+"\n";let result=run(c,&request);assert!(result.status.success());let text=String::from_utf8(result.stdout).unwrap();assert!(text.contains("codex_floatboard_dev.report_progress"));assert!(!text.contains("调用 codex_floatboard.report_progress"));fs::remove_dir_all(fixture).unwrap();
}
